            pas[i][j] = (pas[i-1][j-1] + pas[i-1][j]) % MOD;
        }
    }

    // Matrix class
    class Matrix {
        constructor(n, data = null) {
            this.n = n;
            if (data) {
                this.a = data;
            } else {
                this.a = Array(n).fill(0).map(() => Array(n).fill(0n));
            }
        }

        static identity(n) {
            const a = Array(n).fill(0).map(() => Array(n).fill(0n));
            for (let i = 0; i < n; i++) a[i][i] = 1n;
            return new Matrix(n, a);
        }

