                const Ai = A[i];
                const resi = res[i];
                for (let k = 0; k < n; k++) {
                    const Aik = Ai[k];
                    if (Aik === 0n) continue;
                    const Bk = B[k];
                    for (let j = 0; j < n; j++) {
                        resi[j] = (resi[j] + Aik * Bk[j]) % MOD;
