            return new Matrix(n, res);
        }

        modpow(exp) {
            if (exp === 0n) return Matrix.identity(this.n);
            if (exp === 1n) return this;
            let half = this.modpow(exp / 2n);
            half = half.multiply(half);
            if (exp % 2n === 1n) half = half.multiply(this);
            return half;
        }
    }

    const SIZE = 83;
    const a = new Matrix(SIZE);
    // a.a[0][0] = 1;
    a.a[0][0] = 1n;
    // a.a[0][k+1] = 1;
    a.a[0][k+1] = 1n;

    for (let pot = 0; pot <= 40; pot++) {
        for (let coef = 0; coef <= pot; coef++) {
            const val = pas[pot][coef];
            // a.a[pot+1][coef+1] = pas[pot][coef];
            a.a[pot+1][coef+1] = val;
            // a.a[pot+1][coef+42] = (pas[pot][coef] * ((1L << (pot-coef)) % mod)) % mod;
            const shift = 1n << BigInt(pot - coef);
            a.a[pot+1][coef+42] = (val * (shift % MOD)) % MOD;
        }
