    }

    const b = new Matrix(SIZE);
    for (let i = 1; i <= 42; i++) {
        b.a[i][0] = 1n;
    }

    let resMat = a.modpow(n);
    resMat = resMat.multiply(b);

    console.log(resMat.a[0][0].toString());
}

main();
