const MOD = 1000000007n;

function pas(n, mod) {
    const ret = Array.from({ length: n + 1 }, () => Array(n + 1).fill(0n));
    for (let i = 0; i <= n; i++) {
        ret[i][0] = 1n;
        for (let j = 1; j <= i; j++) {
            ret[i][j] = (ret[i - 1][j - 1] + ret[i - 1][j]) % mod;
        }
    }
    return ret;
}

class Matrix {
    constructor(n, data = null) {
        this.n = n;
        if (data) {
            this.a = data;
        } else {
            this.a = Array.from({ length: n }, () => Array(n).fill(0n));
        }
    }

    static identity(n) {
        const a = Array.from({ length: n }, () => Array(n).fill(0n));
        for (let i = 0; i < n; i++) a[i][i] = 1n;
        return new Matrix(n, a);
    }

    multiply(b, mod) {
        const n = this.n;
        const resp = new Matrix(n);
        for (let i = 0; i < n; i++) {
            for (let k = 0; k < n; k++) {
                const aik = this.a[i][k];
                if (aik === 0n) continue;
                const rowB = b.a[k];
                const rowResp = resp.a[i];
                for (let j = 0; j < n; j++) {
                    rowResp[j] = (rowResp[j] + aik * rowB[j]) % mod;
                }
            }
        }
        return resp;
    }

    modpow(exp, mod) {
        if (exp === 0n) return Matrix.identity(this.n);
        if (exp === 1n) return this;
        const h = this.modpow(exp / 2n, mod);
        let res = h.multiply(h, mod);
        if (exp % 2n === 1n) res = res.multiply(this, mod);
        return res;
    }
}

class Parser {
    constructor(input) {
        this.tokens = input.trim().split(/\s+/);
        this.idx = 0;
    }
    next() {
        return this.tokens[this.idx++];
    }
    nextInt() {
        return parseInt(this.next(), 10);
    }
    nextLong() {
        return BigInt(this.next());
    }
}

class OutputWriter {
    constructor() {
        this.output = [];
    }
    println(...args) {
        this.output.push(args.join(' '));
    }
    close() {
        console.log(this.output.join('\n'));
    }
}

class TaskC {
    constructor() {
        this.mod = MOD;
    }

    solve(testNumber, inParser, outWriter) {
        const n = inParser.nextLong();
        const k = inParser.nextInt();

        const pasTriangle = pas(40, this.mod);
        const a = new Matrix(83);

        a.a[0][0] = 1n;
        a.a[0][k + 1] = 1n;

        for (let pot = 0; pot <= 40; pot++) {
