            }
        }

        for (let pot = 0; pot <= 40; pot++) {
            a.a[pot + 42][pot + 1] = 1n;
        }

        const b = new Matrix(83);
        for (let i = 1; i <= 42; i++) {
            b.a[i][0] = 1n;
        }

        const aPow = a.modpow(n, this.mod);
        const res = aPow.multiply(b, this.mod);

        outWriter.println(res.a[0][0].toString());
    }
}

