const fs = require('fs');

const MOD = 1000000007n;

class Parser {
    constructor(data) {
        this.tokens = data.trim().split(/\s+/);
        this.index = 0;
    }

    next() {
        return this.tokens[this.index++];
    }

    nextInt() {
        return parseInt(this.next(), 10);
    }

    nextLong() {
        return BigInt(this.next());
    }
}

class OutputWriter {
    constructor() {
        this.output = [];
    }

    println(...args) {
        this.output.push(args.join(' '));
    }

    close() {
        console.log(this.output.join('\n'));
    }
}

class MathUtils {
    static pas(n, mod) {
        const ret = Array.from({ length: n + 1 }, () => Array(n + 1).fill(0n));
        for (let i = 0; i <= n; i++) {
            ret[i][0] = 1n;
            for (let j = 1; j <= i; j++) {
                ret[i][j] = (ret[i - 1][j - 1] + ret[i - 1][j]) % mod;
            }
        }
        return ret;
    }
}

class Matrix {
    constructor(n, data = null) {
        this.n = n;
        if (data) {
            this.a = data;
        } else {
            this.a = Array.from({ length: n }, () => Array(n).fill(0n));
        }
    }

    static identity(n) {
        const data = Array.from({ length: n }, (_, i) =>
            Array.from({ length: n }, (_, j) => (i === j ? 1n : 0n))
        );
        return new Matrix(n, data);
    }

    multiply(b, mod) {
        const n = this.n;
        const respData = Array.from({ length: n }, () => Array(n).fill(0n));
        for (let i = 0; i < n; i++) {
            for (let k = 0; k < n; k++) {
                if (this.a[i][k] === 0n) continue;
                const aik = this.a[i][k];
                for (let j = 0; j < n; j++) {
                    respData[i][j] = (respData[i][j] + aik * b.a[k][j]) % mod;
                }
            }
        }
        return new Matrix(n, respData);
    }

    modpow(exp, mod) {
        if (exp === 0n) return Matrix.identity(this.n);
        if (exp === 1n) return this;

        let half = this.modpow(exp / 2n, mod);
        half = half.multiply(half, mod);
        if (exp % 2n === 1n) {
            half = half.multiply(this, mod);
        }
        return half;
    }
}

function solve() {
    const input = fs.readFileSync(0, 'utf-8');
    const inParser = new Parser(input);
    const out = new OutputWriter();

    const n = inParser.nextLong();
    const k = inParser.nextInt();

    const pas = MathUtils.pas(41, MOD);
    const a = new Matrix(83);

    a.a[0][0] = 1n;
    a.a[0][k + 1] = 1n;

    for (let pot = 0; pot <= 40; pot++) {
        for (let coef = 0; coef <= pot; coef++) {
            const val = pas[pot][coef];
            a.a[pot + 1][coef + 1] = val;
            const shift = (1n << BigInt(pot - coef)) % MOD;
            a.a[pot + 1][coef + 42] = (val * shift) % MOD;
        }
    }

    for (let pot = 0; pot <= 40; pot++) {
        a.a[pot + 42][pot + 1] = 1n;
    }

    const bData = Array.from({ length: 83 }, (_, i) =>
        Array.from({ length: 83 }, (_, j) => (j === 0 && i >= 1 && i <= 42 ? 1n : 0n))
    );
    const b = new Matrix(83, bData);

    let aPow = a.modpow(n, MOD);
    aPow = aPow.multiply(b, MOD);

    out.println(aPow.a[0][0].toString());
    out.close();
}

solve();

